// SANDBOX routing — same rules as the planned production workflow.
// Payload comes from src/lib/email/sender.ts (sendEmailById).
const item = $input.first().json;
const tk = item.template_key || (item.metadata && item.metadata.template_key) || 'unknown';

const ROUTES = {
  // admin / internal
  new_lead: 'admin',
  // customer lifecycle
  welcome: 'customer',
  change_request_received: 'customer',
  change_request_preview_ready: 'customer',
  change_published: 'customer',
  change_rejected: 'customer',
  // billing / payments
  payment_success: 'billing',
  payment_failed: 'billing',
  invoice_created: 'billing',
  invoice_paid: 'billing',
  // hosting
  hosting_expiring_soon: 'billing',
  hosting_expired: 'billing',
  hosting_renewed: 'billing',
};

const route = ROUTES[tk] || 'system';
return [{
  json: {
    ...item,
    template_key: tk,
    route,
    sandbox: true,
    received_at: new Date().toISOString(),
  },
}];

// SANDBOX delivery — NO real email is ever sent.
// The payload is appended to a local log file, which stands in for the
// production SMTP/email provider node. Returns 200 so sender.ts marks
// the queue item as 'sent' (sandbox verification only).
const item = $input.first().json;
const fs = require('fs');
const line = JSON.stringify({
  ts: new Date().toISOString(),
  template_key: item.template_key,
  route: item.route,
  to: item.to,
  subject: item.subject,
  sandbox: true,
  note: 'SANDBOX — logged only, no real email sent',
});
fs.appendFileSync('/tmp/n8n-sandbox-delivery.log', line + '\n');
return [{
  json: {
    ok: true,
    delivered: 'sandbox_log',
    route: item.route,
    template_key: item.template_key,
    to: item.to,
  },
}];
